import{_ as e,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Marca-texto nos documentos","description":"","frontmatter":{"title":"Marca-texto nos documentos","id":"eproc-marca-texto-documentos","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.12.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-marca-texto-documentos"}],["meta",{"property":"og:url","content":"https://eploc.com.br/manual/funcionalidades/eproc-marca-texto-documentos"}],["meta",{"property":"og:title","content":"Marca-texto nos documentos | Manual do eploc"}],["meta",{"property":"og:description","content":"Manual oficial do eploc, extensão para Chrome e Edge que acelera o trabalho no eproc, SEI e RUPE."}]]},"headers":[],"relativePath":"funcionalidades/eproc-marca-texto-documentos.md","filePath":"funcionalidades/eproc-marca-texto-documentos.md"}'),t={name:"funcionalidades/eproc-marca-texto-documentos.md"};function c(n,a,m,i,d,u){return o(),r("div",null,a[0]||(a[0]=[s('<h1 id="marca-texto-nos-documentos" tabindex="-1">Marca-texto nos documentos <a class="header-anchor" href="#marca-texto-nos-documentos" aria-label="Permalink to &quot;Marca-texto nos documentos&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Em decisões longas, as ordens a cumprir nem sempre estão só no dispositivo: muitas vezes aparecem espalhadas pelos tópicos da fundamentação. Este recurso realça essas ordens automaticamente e deixa você marcar qualquer trecho com um marca-texto. Ordens e marcações podem ser dadas como cumpridas, e uma barra no topo do documento mostra quantas faltam e leva de uma a outra.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, na janela de um documento aberto pela tabela de eventos do processo:</p><ul><li>as ordens são realçadas em decisões, despachos e sentenças (siglas como DESP, DEC, DESPADEC e SENT);</li><li>o marca-texto funciona em qualquer documento em HTML.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><h3 id="encontrar-as-ordens" tabindex="-1">Encontrar as ordens <a class="header-anchor" href="#encontrar-as-ordens" aria-label="Permalink to &quot;Encontrar as ordens&quot;">​</a></h3><ol><li>Abra uma decisão, um despacho ou uma sentença pela tabela de eventos.</li><li>As ordens aparecem com um fundo amarelo claro e sublinhadas, do verbo até o fim da frase. Por exemplo: &quot;Intime-se a parte autora para emendar a inicial.&quot;</li><li>No topo do documento, a barra <strong>Marca-texto</strong> mostra quantas ordens e marcações faltam cumprir. Use as setas para ir à anterior ou à próxima. O trecho pisca por um instante ao chegar nele. Quando há mais de um item, a barra fica presa no topo da janela enquanto você rola o documento.</li></ol><p>O eploc reconhece verbos de comando com &quot;-se&quot;, no singular e no plural: intime-se, cite-se, expeça-se, oficie-se, cumpra-se, certifique-se, aguarde-se, dê-se, remetam-se, arquivem-se e outros. Também reconhece as ordens na primeira pessoa que começam por <strong>Determino</strong> ou <strong>Defiro</strong>. O fecho solto no fim da decisão, num parágrafo só dele (como &quot;Intimem-se. Cumpra-se.&quot;, &quot;P.R.I.&quot; ou &quot;Expeçam-se / diligencie-se o necessário.&quot;), não é realçado nem entra na conta.</p><h3 id="marcar-um-trecho" tabindex="-1">Marcar um trecho <a class="header-anchor" href="#marcar-um-trecho" aria-label="Permalink to &quot;Marcar um trecho&quot;">​</a></h3><ol><li>Selecione o trecho no documento.</li><li>Clique com o botão direito e escolha uma cor: amarelo, verde, rosa ou azul.</li></ol><p>A marcação fica salva e reaparece sempre que o documento for aberto de novo. Para trocar a cor, selecione o mesmo trecho e escolha outra.</p><h3 id="dar-como-cumprido" tabindex="-1">Dar como cumprido <a class="header-anchor" href="#dar-como-cumprido" aria-label="Permalink to &quot;Dar como cumprido&quot;">​</a></h3><p>Clique com o botão direito sobre uma ordem ou uma marcação e escolha <strong>Marcar como cumprida</strong> (ou <strong>cumprido</strong>). O trecho fica riscado, com um sinal de confirmação verde, e sai da contagem da barra. Para desfazer, use <strong>Desmarcar como cumprida</strong> no mesmo menu. Nas marcações, o menu também tem <strong>Remover marcação</strong>.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><ul><li><strong>Realçar automaticamente as ordens nas decisões, despachos e sentenças</strong> (ligada por padrão): desligada, só as marcações feitas por você aparecem.</li></ul><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>PDFs abertos no visualizador do navegador não podem ser marcados. Funciona nos documentos em HTML, como os produzidos no editor do eproc.</li><li>As marcações valem para aquele documento. Se a decisão for retificada e juntada como um novo documento, as marcações não passam para ele.</li><li>As marcações entram no backup e na sincronização com o Google Drive.</li><li>A barra não sai na impressão do documento.</li></ul>',19)]))}const h=e(t,[["render",c]]);export{p as __pageData,h as default};
